import { SkeuoBottomBar } from "./skeuo-bottom-bar";
import type { ComponentProps } from "react";
export function SkeuoDockBar(
  props: Omit<ComponentProps<typeof SkeuoBottomBar>, "variant">,
) {
  return <SkeuoBottomBar {...props} variant="dock" />;
}

import React from "react";
import { Pressable, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { useFeedback, useSkeuo } from "./theme";
import { SkeuoGlyph } from "./icons";
export type BottomBarVariant = "dock" | "keys" | "rail" | "pill";
export type BottomBarItem = {
  value: string;
  label: string;
  icon?: React.ReactNode;
  disabled?: boolean;
};
export function SkeuoBottomBar({
  items,
  value,
  onValueChange,
  variant = "dock",
  bottomInset = 0,
}: {
  items: BottomBarItem[];
  value: string;
  onValueChange: (value: string) => void;
  variant?: BottomBarVariant;
  bottomInset?: number;
}) {
  const { colors: c } = useSkeuo();
  const feedback = useFeedback();
  return (
    <View
      accessibilityRole="tablist"
      accessibilityLabel="Bottom navigation"
      style={{
        paddingBottom: Math.max(8, bottomInset),
        paddingTop: 12,
        paddingHorizontal: variant === "rail" ? 0 : 12,
        backgroundColor: c.background,
      }}
    >
      <View
        style={{
          flexDirection: "row",
          gap: variant === "keys" ? 8 : 2,
          padding: variant === "dock" ? 6 : variant === "pill" ? 5 : 0,
          borderWidth: variant === "dock" || variant === "pill" ? 1 : 0,
          borderColor: c.edge,
          borderRadius: variant === "pill" ? 32 : 16,
          backgroundColor: variant === "keys" ? c.background : c.well,
        }}
      >
        {items.map((item) => {
          const active = item.value === value;
          return (
            <Pressable
              key={item.value}
              accessibilityRole="tab"
              aria-selected={active}
              aria-disabled={!!item.disabled}
              accessibilityLabel={item.label}
              accessibilityState={{
                selected: active,
                disabled: !!item.disabled,
              }}
              disabled={item.disabled}
              onPress={() => {
                feedback();
                onValueChange(item.value);
              }}
              style={({ pressed }) => ({
                flex: 1,
                minHeight: 60,
                borderRadius: variant === "pill" ? 26 : 10,
                borderWidth:
                  variant === "keys" || (active && variant === "dock") ? 1 : 0,
                borderBottomWidth:
                  variant === "keys"
                    ? pressed
                      ? 1
                      : 4
                    : active && variant === "rail"
                      ? 3
                      : 1,
                borderColor: active && variant === "rail" ? c.accent : c.edge,
                backgroundColor: active
                  ? c.raised
                  : variant === "keys"
                    ? c.surface
                    : "transparent",
                opacity: item.disabled ? 0.4 : 1,
                transform: [{ translateY: pressed ? 2 : 0 }],
                overflow: "hidden",
              })}
            >
              <LinearGradient
                colors={active ? [c.raised, c.surface] : [c.well, c.well]}
                style={{
                  flex: 1,
                  alignItems: "center",
                  justifyContent: "center",
                  paddingVertical: 8,
                  gap: 3,
                }}
              >
                {item.icon ?? (
                  <SkeuoGlyph
                    name={item.value}
                    color={active ? c.accent : c.muted}
                  />
                )}
                <Text
                  numberOfLines={1}
                  style={{
                    fontSize: 10,
                    fontWeight: active ? "700" : "500",
                    color: active ? c.ink : c.muted,
                  }}
                >
                  {item.label}
                </Text>
              </LinearGradient>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import { Text } from "react-native";
/** Simple line symbols keep the portable controls independent of an icon package. Hosts may pass their own icons. */
export function SkeuoGlyph({
  name,
  color = "#686863",
  size = 21,
}: {
  name: string;
  color?: string;
  size?: number;
}) {
  const symbols: Record<string, string> = {
    home: "⌂",
    transactions: "⇄",
    analysis: "▥",
    profile: "○",
    focus: "◷",
    habits: "✓",
    journal: "≡",
    settings: "⚙",
    activity: "↗",
    goals: "◎",
    saved: "▱",
    add: "+",
    arrow: "↗",
    back: "‹",
    next: "›",
    play: "▶",
    pause: "Ⅱ",
    sound: "♪",
  };
  return (
    <Text
      accessible={false}
      style={{
        color,
        fontSize: size,
        lineHeight: size + 4,
        textAlign: "center",
      }}
    >
      {symbols[name] ?? "◇"}
    </Text>
  );
}
